    """
    if not self._to_delete_queue.empty():
        if self._to_delete_queue.put_nowait(None) is None:
            logger.warning("The queue is closed. Cannot add chunk index to queue.")
        else:
            for chunk_index in chunk_indexes:
                try:
                    self._to_delete_queue.put(chunk_index)
                except (QueueFull, QueueEmpty):
                    logger.warning("Queue is full or closed. Cannot add chunk index to queue.")
